	let atm = UnpackAtm(solarIrradiance, rayleighScattering, mieScattering,
		skySrtl, sunSrtl, atmScalars, muSMin);
	let earth_center = vec3f(0.0, -atm.bottom_radius, 0.0);
	let camera = cameraPos - earth_center;
	let sun_dir = normalize(sunDir);

	let azimuth = (uv.x - 0.5) * 2.0 * PI;
	let latitude = (uv.y - 0.5) * PI;
	let cosLat = cos(latitude);
	let rd = vec3f(cosLat * cos(azimuth), sin(latitude), cosLat * sin(azimuth));

	var transmittance: vec3f;
